// Keep the map engine local: loading a map must not depend on a script CDN.
const fs = require('node:fs');
const path = require('node:path');
const root = path.dirname(require.resolve('leaflet/package.json'));
const out = path.join(__dirname, '../src/generated');
fs.mkdirSync(out, { recursive: true });
const js = fs
  .readFileSync(path.join(root, 'dist/leaflet.js'), 'utf8')
  .replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(path.join(root, 'dist/leaflet.css'), 'utf8');
fs.writeFileSync(
  path.join(out, 'leaflet-assets.ts'),
  '// @generated by tools/generate-leaflet-assets.cjs; Leaflet 1.9.4, BSD-2-Clause.\n' +
    '// prettier-ignore\nexport const leafletJs = ' +
    JSON.stringify(js) +
    ';\n' +
    '// prettier-ignore\nexport const leafletCss = ' +
    JSON.stringify(css) +
    ';\n',
);
fs.copyFileSync(path.join(root, 'LICENSE'), path.join(out, 'LEAFLET-LICENSE.txt'));
